const requisitionInbox = `-- name: RequisitionInbox :many
SELECT r.id AS requisition_id, r.sr_number, r.est_total, r.department_id, d.name AS department_name, r.requester_id, u.full_name AS requester_name, r.submitted_at,
       s.id AS step_id, s.level_no, s.name AS step_name
  FROM inv_approval_steps s
  JOIN inv_requisitions r ON r.property_id = s.property_id AND r.id = s.requisition_id AND r.status = 'SUBMITTED' AND r.cycle = s.cycle
  JOIN users u ON u.tenant_id = r.tenant_id AND u.id = r.requester_id
  LEFT JOIN departments d ON d.property_id = r.property_id AND d.id = r.department_id
  LEFT JOIN departments pd ON pd.property_id = d.property_id AND pd.id = d.parent_id
 WHERE s.tenant_id = $1 AND s.property_id = $2 AND s.status = 'ACTIVE' AND r.requester_id <> $3
   AND NOT EXISTS (SELECT 1 FROM inv_approval_steps x WHERE x.requisition_id = s.requisition_id AND x.cycle = s.cycle AND x.status = 'APPROVED' AND x.decided_by = $3)
   AND (
        (s.approver_kind = 'PERMISSION' AND ($4::boolean OR EXISTS (
            SELECT 1 FROM user_properties up JOIN role_permissions rp ON rp.role_id = up.role_id
             WHERE up.tenant_id = $1 AND up.user_id = $3 AND up.property_id = $2 AND rp.permission_code = s.permission)))
        OR
        (s.approver_kind = 'DEPT_HEAD'
         AND $3 IN (CASE WHEN d.head_user_id IS NOT NULL THEN d.head_user_id ELSE pd.head_user_id END, CASE WHEN d.head_user_id IS NOT NULL THEN d.deputy_user_id ELSE pd.deputy_user_id END)
         AND ($4::boolean OR EXISTS (
            SELECT 1 FROM user_properties up JOIN role_permissions rp ON rp.role_id = up.role_id
             WHERE up.tenant_id = $1 AND up.user_id = $3 AND up.property_id = $2 AND rp.permission_code = 'inventory.dept_approve')))
       )
 ORDER BY r.submitted_at, r.id
`

