const warehouseDepartment = `-- name: WarehouseDepartment :one
SELECT w.id, w.kind, w.outlet_id, COALESCE(w.department_id, o.department_id, 0)::bigint AS department_id
  FROM inv_warehouses w LEFT JOIN pos_outlets o ON o.property_id = w.property_id AND o.id = w.outlet_id
 WHERE w.tenant_id = $1 AND w.property_id = $2 AND w.id = $3
`

type WarehouseDepartmentParams struct {
	TenantID   int64
	PropertyID int64
	ID         int64
}

type WarehouseDepartmentRow struct {
	ID           int64
	Kind         string
	OutletID     *int64
	DepartmentID int64
}

// The department a warehouse stands for: its own, else its outlet's.
func (q *Queries) WarehouseDepartment(ctx context.Context, arg WarehouseDepartmentParams) (WarehouseDepartmentRow, error) {
	row := q.db.QueryRow(ctx, warehouseDepartment, arg.TenantID, arg.PropertyID, arg.ID)
	var i WarehouseDepartmentRow
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.OutletID,
		&i.DepartmentID,
	)
	return i, err
}
